// ═══════════════════════════════════════════════════════════
// CALL SHEET — the per-client fields the SDR's call sheet is built from,
// and the "Call sheet" links.
// ═══════════════════════════════════════════════════════════
//
// The sheet itself is a Google Doc generated by the call-sheet-build edge
// function. A DB trigger on clients queues a rebuild whenever one of these
// fields changes, so an edit here shows up on the sheet within a minute.
// Nobody edits the doc by hand — it is overwritten on every build.
//
// Fields save straight to the row (debounced), not through Settings'
// buildClientUpdate whitelist, so the batch autosave never touches them.
// The call_* columns have no FIELD_MAP entry, so they live on the client
// object under their snake_case names.

import { state } from './app.js?v=20261030042402';
import { esc, str, svgIcon } from './utils.js?v=20261030042402';
import { isAdmin, isEmployee } from './auth.js?v=20261030042402';
import { sbUpdateClient, showToast } from './api.js?v=20261030042402';
import { invokeEdgeFunctionAsUser } from './edge-auth.js?v=20261030042402';
import { findClientForDeal } from './client-info.js?v=20261030042402';

// [client key, column, label, hint, rows]. rows 1 = single-line input.
const FIELDS = [
  ['call_meets_lead', 'call_meets_lead', 'Who meets the lead', 'e.g. Jerry Grzan, Owner (he does the walk-through himself)', 1],
  ['call_display_name', 'call_display_name', 'Company name as the SDR says it', 'Blank = CRM name without LLC / Inc.', 1],
  ['call_shop', 'call_shop', 'Shop (where they are based)', 'e.g. Buford, GA. Say "we\'re out of the Suwanee / Buford area." Blank = Location', 1],
  ['call_caller_id', 'call_caller_id', 'Caller ID', 'JustCall number the SDR dials from (optional)', 1],
  ['calendlyUrl', 'calendly_url', 'Calendly link (Book)', 'https://calendly.com/...', 1],
  ['call_booking_notes', 'call_booking_notes', 'Booking notes', 'One per line. A line starting "Until then:" only shows while there is no Calendly link.', 2],
  ['call_coverage', 'call_coverage', 'Covers (service area in words)', 'Further lines print under it, e.g. a separate snow area', 3],
  ['call_min_job_size', 'call_min_job_size', 'Minimum job size', 'e.g. nothing under about $1,000/month', 1],
  ['call_areas_avoid', 'call_areas_avoid', 'Areas to avoid (Not in area)', 'e.g. Kennesaw or anything west of Marietta', 2],
  ['call_property_types_want', 'call_property_types_want', 'Property types they want (Who we want)', 'e.g. HOAs · apartments · office parks', 3],
  ['call_property_types_avoid', 'call_property_types_avoid', 'Property types they don\'t want (Do NOT pitch)', 'e.g. single-family homes · one-off small jobs', 2],
  ['call_do_not_call', 'call_do_not_call', 'Do NOT call (named companies)', 'Current customers or open deals the SDR must never call (optional)', 2],
  ['managedProperties', 'managed_properties', 'Reference accounts (the client\'s own customers)', 'One per line: Name (type) | address. The first 10 print as examples; the deal card\'s Properties button shows all.', 6],
  ['call_reference_note', 'call_reference_note', 'Note under the reference accounts', 'e.g. 79 accounts in total (Mike\'s list)', 2],
  ['services', 'services', 'Services (We do)', 'One per line', 5],
  ['call_services_not', 'call_services_not', 'Services they don\'t do (Not)', 'e.g. tree work over 12 ft', 1],
  ['call_quick_lines', 'call_quick_lines', 'Quick lines (selling points)', 'One per line', 5],
  ['call_get_extra', 'call_get_extra', 'Extra to get before hanging up', 'One per line. A line starting like a standard item ("meet on site or drop by") replaces it.', 2],
  ['call_confirmation_email', 'call_confirmation_email', 'Confirmation email (optional)', 'The email sent after booking that adds whoever meets the lead to the thread. One paragraph per line.', 6],
];

const _timers = {};

function client(id) {
  return state.clients.find(c => str(c.id) === str(id));
}

function shownValue(c, key) {
  const v = c[key];
  return Array.isArray(v) ? v.join('\n') : str(v ?? '');
}

// Accepts a pasted folder URL or a bare id.
export function driveFolderId(text) {
  const m = str(text).match(/folders\/([\w-]+)/);
  return m ? m[1] : str(text).trim();
}

function saveCallSheetField(clientId, key, text) {
  const c = client(clientId);
  const f = FIELDS.find(x => x[0] === key) || (key === 'drive_folder_id' && [key, key]);
  if (!c || !f) return;
  const column = f[1];
  const value = key === 'services' ? text.split('\n').map(s => s.trim()).filter(Boolean)
    : key === 'drive_folder_id' ? driveFolderId(text)
    : text;
  c[key] = value;
  clearTimeout(_timers[clientId + key]);
  _timers[clientId + key] = setTimeout(() => {
    sbUpdateClient(c.id, { [column]: value === '' ? null : value })
      .catch(e => showToast('Call sheet field not saved: ' + e.message, 'error'));
  }, 800);
}

async function rebuildCallSheet(clientId) {
  const c = client(clientId);
  showToast('Rebuilding the call sheet…');
  try {
    const res = await invokeEdgeFunctionAsUser('call-sheet-build', { clientId });
    const b = (res.built || [])[0];
    if (!b) throw new Error((res.failed || [])[0]?.error || 'nothing built');
    if (c) { c.call_sheet_url = b.url; c.call_sheet_error = ''; }
    showToast(b.missing.length ? `Call sheet rebuilt. Still missing: ${b.missing.join(', ')}` : 'Call sheet rebuilt', 'success');
  } catch (e) {
    showToast('Call sheet rebuild failed: ' + e.message, 'error');
  }
}

window.saveCallSheetField = saveCallSheetField;
window.rebuildCallSheet = rebuildCallSheet;

function linkButton(url, label) {
  return `<a href="${esc(url)}" target="_blank" rel="noopener" onclick="event.stopPropagation()" style="display:inline-flex;align-items:center;gap:4px;padding:5px 12px;background:#e0f2fe;border:1px solid #7dd3fc;border-radius:6px;font-size:11px;font-weight:600;color:#0369a1;text-decoration:none">${svgIcon('external-link', 12)} ${esc(label)}</a>`;
}

// ─── Settings: one section per client ───
export function renderCallSheetSettings(c) {
  const id = esc(c.id);
  const input = 'width:100%;box-sizing:border-box;padding:6px 10px;border:1px solid var(--border);border-radius:6px;font-size:12px;font-family:var(--font);background:var(--card);color:var(--text);margin-top:3px';
  const url = str(c.call_sheet_url);
  const err = str(c.call_sheet_error);
  const built = str(c.call_sheet_built_at);
  let h = `<details style="margin-bottom:8px;padding:10px;background:#f0f9ff;border:1px solid #bae6fd;border-radius:8px">
    <summary style="font-size:10px;font-weight:700;color:#0369a1;text-transform:uppercase;letter-spacing:.5px;cursor:pointer">Call Sheet</summary>
    <div style="display:flex;gap:6px;align-items:center;margin:8px 0;flex-wrap:wrap">
      ${url ? linkButton(url, 'Open call sheet') : '<span style="font-size:11px;color:var(--text-muted)">No call sheet yet — it is created within a minute of the first save.</span>'}
      <button onclick="rebuildCallSheet('${id}')" style="padding:5px 12px;background:#0369a1;color:#fff;border:none;border-radius:6px;font-size:11px;font-weight:600;cursor:pointer">Rebuild now</button>
      ${built ? `<span style="font-size:10px;color:var(--text-muted)">Built ${esc(new Date(built).toLocaleString('en-US', { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }))}</span>` : ''}
    </div>
    ${err ? `<div style="font-size:11px;color:#b91c1c;margin-bottom:8px">Last build failed: ${esc(err)}</div>` : ''}
    <div style="font-size:10px;color:var(--text-muted);margin-bottom:8px">Edits here rebuild the Google Doc within a minute. Don't edit the doc itself; it is overwritten. Anything left blank shows on the sheet as "⚠️ MISSING".</div>`;
  for (const [key, , label, hint, rows] of FIELDS) {
    const val = esc(shownValue(c, key));
    const on = `oninput="saveCallSheetField('${id}','${key}',this.value)"`;
    h += `<div style="margin-bottom:8px">
      <label style="font-size:10px;font-weight:600;color:var(--text-muted)">${esc(label)}</label>
      ${rows > 1
        ? `<textarea rows="${rows}" placeholder="${esc(hint)}" ${on} style="${input};resize:vertical">${val}</textarea>`
        : `<input type="text" placeholder="${esc(hint)}" value="${val}" ${on} style="${input}">`}
      ${rows > 1 ? `<div style="font-size:9px;color:var(--text-muted);margin-top:2px">${esc(hint)}</div>` : ''}
    </div>`;
  }
  h += `<div style="margin-bottom:2px">
      <label style="font-size:10px;font-weight:600;color:var(--text-muted)">Client Drive folder</label>
      <input type="text" placeholder="Folder URL. Blank = found by name under Clients" value="${esc(str(c.drive_folder_id))}"
        oninput="saveCallSheetField('${id}','drive_folder_id',this.value)" style="${input}">
      <div style="font-size:9px;color:var(--text-muted);margin-top:2px">The sheet lives in this folder's "Cold Calling" subfolder, with a shortcut in Client SDR › Client Call sheets.</div>
    </div>
  </details>`;
  return h;
}

// ─── Onboarding (Settings › Parse Doc) ───
// parse-onboarding-doc extracts these alongside its own fields; the confirm modal
// shows them under "Call sheet" and saveOnboardingData() merges the result in.
// [parsed key, client key, label]
const ONBOARDING = [
  ['callMeetsLead', 'call_meets_lead', 'Who meets the lead'],
  ['callShop', 'call_shop', 'Shop (where they are based)'],
  ['callCoverage', 'call_coverage', 'Covers (service area in words)'],
  ['callMinJobSize', 'call_min_job_size', 'Minimum job size'],
  ['callAreasAvoid', 'call_areas_avoid', 'Areas to avoid'],
  ['callPropertyTypesWant', 'call_property_types_want', 'Property types they want'],
  ['callPropertyTypesAvoid', 'call_property_types_avoid', 'Property types they don\'t want'],
  ['callServicesNot', 'call_services_not', 'Services they don\'t do'],
  ['callQuickLines', 'call_quick_lines', 'Quick lines (one per line)'],
  ['referenceAccounts', 'managedProperties', 'Reference accounts (Name (type) | address)'],
];

export function renderCallSheetOnboardingFields(parsed, field) {
  return `<div style="margin:12px 0 6px;font-size:11px;font-weight:700;color:#0369a1;text-transform:uppercase;letter-spacing:.5px">Call sheet</div>`
    + ONBOARDING.map(([k, , label]) => field(label, k, parsed[k], 'textarea')).join('');
}

// Fill-only: a field the team already set in Settings is never overwritten by a
// re-parse. Reference accounts append, because managed_properties is also the
// client's do-not-contact list. Services come from the modal's Services box.
export function callSheetOnboardingUpdates(val, c, servicesText) {
  const u = {};
  for (const [k, key] of ONBOARDING) {
    const v = val(k);
    if (!v) continue;
    if (key === 'managedProperties') {
      const have = str(c?.managedProperties).trim();
      const fresh = v.split('\n').map(s => s.trim()).filter(l => l && !have.toLowerCase().includes(l.split('|')[0].trim().toLowerCase()));
      if (fresh.length) u.managedProperties = [have, ...fresh].filter(Boolean).join('\n');
    } else if (!str(c?.[key]).trim()) {
      u[key] = v;
    }
  }
  const services = str(servicesText).split('\n').map(s => s.replace(/^[-•*]\s*/, '').trim()).filter(Boolean);
  if (services.length && !(Array.isArray(c?.services) && c.services.length)) u.services = services;
  return u;
}

// ─── "Call sheet" link: deal card + client panel ───
// Staff only, like the Properties button beside it. Inline onclick for the same
// reason: the deal modal stops click propagation.
export function renderCallSheetLink(clientOrDeal) {
  if (!(isAdmin() || isEmployee())) return '';
  const c = clientOrDeal && 'pipeline' in clientOrDeal ? findClientForDeal(clientOrDeal) : clientOrDeal;
  const url = c && str(c.call_sheet_url);
  return url ? `<div class="form-group form-span2" style="margin-top:0">${linkButton(url, `${c.name} — Call sheet`)}</div>` : '';
}
